const env = (k) => { try { return String($env[k] ?? ''); } catch (e) { return ''; } };  // '' when unset or blocked
// Which services to watch. N8N_HEALTH_URLS = "api=http://api:8000/health,gateway=http://gateway:8000/health,..."
// Empty (the default) = standalone: nothing to watch, the run ends here. The test form simulates instead.
const SERVICES = ['api', 'agent', 'gateway', 'risk', 'extractor'];
if ($('Test form').isExecuted) {
  const down = String($('Test form').first().json['Services that are down'] ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  return SERVICES.map((name) => ({ json: { name, simulated: true, up: !down.includes(name) } }));
}
const urls = env('N8N_HEALTH_URLS').split(',').map((s) => s.trim()).filter(Boolean);
return urls.map((pair) => {
  const i = pair.indexOf('=');
  if (i < 1) throw new Error(`N8N_HEALTH_URLS entry "${pair}" is not name=url`);
  return { json: { name: pair.slice(0, i).trim(), url: pair.slice(i + 1).trim(), simulated: false } };
});

// Turns the answers into up/down and alerts only on a change, plus a reminder every hour while still down.
// n8n decides nothing about payments: if this watch is wrong, only a message is wrong.
const test = $('Test form').isExecuted;
const asked = $('Services').all();
const results = $input.all().map((item, i) => {
  const name = asked[i].json.name;
  if (asked[i].json.simulated) return { name, up: asked[i].json.up, why: asked[i].json.up ? 'ok' : 'simulated: no answer' };
  const r = item.json;
  const up = r.statusCode === 200 && (r.body ?? {}).status === 'ok';
  const why = up ? 'ok' : r.error ? String(r.error.message ?? r.error).slice(0, 80) : `HTTP ${r.statusCode ?? 'none'}`;
  return { name, up, why };
});
const now = Date.now();
const stamp = (ms) => new Date(ms).toISOString().slice(0, 16).replace('T', ' ') + ' UTC';
const state = test ? { down: {} } : $getWorkflowStaticData('global');  // test runs never touch the real state
state.down = state.down ?? {};
const newly = [], still = [], recovered = [];
for (const r of results) {
  const since = state.down[r.name];
  if (!r.up && since === undefined) { state.down[r.name] = now; newly.push(r); }
  else if (!r.up) still.push({ ...r, since });
  else if (since !== undefined) { delete state.down[r.name]; recovered.push({ ...r, since }); }
}
const remind = still.length > 0 && now - (state.last_alert ?? 0) >= 3600000;
const alert = newly.length > 0 || remind;
if (alert && !test) state.last_alert = now;
const lines = [];
for (const r of newly) lines.push(`DOWN  ${r.name}: ${r.why}`);
for (const r of still) lines.push(`STILL DOWN  ${r.name} since ${stamp(r.since)}: ${r.why}`);
for (const r of recovered) lines.push(`RECOVERED  ${r.name} (was down since ${stamp(r.since)})`);
const up = results.filter((r) => r.up).map((r) => r.name);
const head = (test ? 'TEST (simulated, nothing was called): ' : '') + (newly.length || still.length ? 'SecureFin services DOWN' : 'SecureFin services all up');
const summary = [head, ...lines, `up: ${up.join(', ') || 'none'}`].join('\n');
return [{ json: { alert, test, summary, down: [...newly, ...still].map((r) => r.name), recovered: recovered.map((r) => r.name) } }];
